def compute(vars):
    value_2018 = vars["v1"]
    value_2017 = vars["v2"]

    if value_2018 > value_2017:
        higher_year = 2018
    elif value_2017 > value_2018:
        higher_year = 2017
    else:
        higher_year = None

    return {
        "value": higher_year,
        "trace": {
            "v1": value_2018,
            "v2": value_2017,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
